pub fn objectAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "position")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "normal0")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "texcoord0")) {
        return 2;
    }
    return null;
}
pub fn objectTextureSlot(tex_name: []const u8) ?usize {
    if (std.mem.eql(u8, tex_name, "diffuse_texture")) {
        return 0;
    }
    if (std.mem.eql(u8, tex_name, "specular_texture")) {
        return 1;
    }
    return null;
}
pub fn objectSamplerSlot(smp_name: []const u8) ?usize {
    if (std.mem.eql(u8, smp_name, "texture_sampler")) {
        return 0;
    }
    return null;
}
pub fn objectUniformBlockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "object_vs_params")) {
        return 0;
    }
    if (std.mem.eql(u8, ub_name, "lighting_fs_params")) {
        return 1;
    }
    return null;
}
pub fn objectUniformBlockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "object_vs_params")) {
        return @sizeOf(ObjectVsParams);
    }
    if (std.mem.eql(u8, ub_name, "lighting_fs_params")) {
        return @sizeOf(LightingFsParams);
    }
    return null;
}
pub fn objectUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "object_vs_params")) {
        if (std.mem.eql(u8, u_name, "mvp")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "model")) {
            return 64;
        }
    }
    if (std.mem.eql(u8, ub_name, "lighting_fs_params")) {
        if (std.mem.eql(u8, u_name, "material_properties")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "light_position")) {
            return 16;
        }
        if (std.mem.eql(u8, u_name, "light_direction")) {
            return 32;
        }
        if (std.mem.eql(u8, u_name, "light_ambient")) {
            return 48;
        }
        if (std.mem.eql(u8, u_name, "light_diffuse")) {
            return 64;
        }
        if (std.mem.eql(u8, u_name, "light_specular")) {
            return 80;
        }
        if (std.mem.eql(u8, u_name, "attenuation_terms")) {
            return 96;
        }
        if (std.mem.eql(u8, u_name, "spotlight_cutoffs")) {
            return 112;
        }
        if (std.mem.eql(u8, u_name, "view_position")) {
            return 128;
        }
    }
    return null;
}
